return ['domain'=>'zinn-translate','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ta_IN','project-id-version'=>'zinn-translate','pot-creation-date'=>'2026-10-02T10:29:43+00:00','po-revision-date'=>'2026-10-02T10:29:43+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Translate'=>'Zinn® Translate','https://zinndigital.com/wordpress-plugins/zinn-translate'=>'https://zinndigital.com/wordpress-plugins/zinn-translate','Publishes this site in every language you choose, on its own web addresses, with translated slugs, metadata, menus, WooCommerce products, hreflang, per-language sitemaps and llms.txt. Translate with your Zinn Digital® plan or with your own provider key.'=>'நீங்கள் தேர்ந்தெடுக்கும் ஒவ்வொரு மொழியிலும், அதன் சொந்த வலை முகவரிகளில், மொழிபெயர்க்கப்பட்ட சிலக்குகள், மெட்டாடேட்டா, மெனுக்கள், WooCommerce தயாரிப்புகள், hreflang, மொழி வாரியான தள வரைபடங்கள் மற்றும் llms.txt ஆகியவற்றுடன் இந்த தளத்தை வெளியிடுகிறது. உங்கள் Zinn Digital® திட்டம் மூலமாகவோ அல்லது உங்கள் சொந்த வழங்குநர் விசை மூலமாகவோ மொழிபெயர்க்கவும்.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'சேமிக்கப்பட்டது. அதை மாற்ற புதிய மதிப்பை உள்ளிடவும்.','Filter this list…'=>'இந்தப் பட்டியலை வடிகட்டவும்…','Filter this list'=>'இப்பட்டியலை வடிகட்டவும்','Nothing matches that filter.'=>'அந்த வடிப்பானுடன் எதுவும் பொருந்தவில்லை.','Add a row'=>'ஒரு வரிசையைச் சேர்','Remove this row'=>'இந்த வரியை நீக்குக','Remove'=>'நீக்கு','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — மேலோட்டம்','Overview'=>'கண்ணோட்டம்','Copied'=>'நகலெடுக்கப்பட்டது','Every Zinn® plugin on this site, and whether it is working.'=>'இந்த தளத்தில் உள்ள ஒவ்வொரு Zinn® செருகுநிரலும், அது செயல்படுகிறதா என்பதும்.','No connection is needed for this plugin.'=>'இந்தச் செருகுநிரலுக்கு இணைப்பு எதுவும் தேவையில்லை.','Open settings'=>'அமைப்புகளைத் திறக்கவும்','You do not have permission to change these settings.'=>'இந்த அமைப்புகளை மாற்றுவதற்கான அனுமதி உங்களுக்கு இல்லை.','Settings sections'=>'அமைப்புகள் பிரிவுகள்','Support'=>'ஆதரவு','Save changes'=>'மாற்றங்களைச் சேமிக்கவும்','Tools'=>'கருவிகள்','Export settings'=>'அமைப்புகளை ஏற்றுமதி செய்','Reset to defaults'=>'இயல்புநிலைக்கு மீட்டமை','This puts every setting on this plugin back to its default. Continue?'=>'இது இந்தச் செருகுநிரலின் ஒவ்வொரு அமைப்பையும் அதன் இயல்புநிலைக்கு மாற்றும். தொடர விரும்புகிறீர்களா?','Diagnostics for support'=>'ஆதரவிற்கான கண்டறிதல்','Import a settings file'=>'அமைப்புகள் கோப்பை இறக்குமதி செய்யவும்','Import'=>'இறக்குமதி செய்','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'ஏற்றுமதி செய்யப்பட்ட கோப்புகளில் கடவுச்சொற்கள், டோக்கன்கள் அல்லது API விசைகள் ஒருபோதும் இருக்காது — புதிய தளத்தில் அவற்றை மீண்டும் உள்ளிட வேண்டும்.','Settings saved.'=>'அமைப்புகள் சேமிக்கப்பட்டன.','Every setting on this plugin is back to its default.'=>'இந்தச் செருகுநிரலின் ஒவ்வொரு அமைப்பும் அதன் இயல்புநிலைக்குத் திரும்பியது.','Done.'=>'முடிந்தது.','That action is not available.'=>'அந்தச் செயல் கிடைக்கவில்லை.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'அந்தக் கோப்பைப் படிக்க முடியவில்லை. Zinn® செருகுநிரலிலிருந்து ஏற்றுமதி செய்யப்பட்ட அமைப்புகள் கோப்பைத் தேர்ந்தெடுக்கவும்.','That file is too large to be a settings export.'=>'அந்தக் கோப்பு அமைப்புகள் ஏற்றுமதியாக இருப்பதற்கு மிகவும் பெரியதாக உள்ளது.','That file is not a Zinn® settings export.'=>'அந்தக் கோப்பு Zinn® அமைப்புகளின் ஏற்றுமதி அல்ல.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'அந்தக் கோப்பு வேறு செருகுநிரலிலிருந்து (%s) ஏற்றுமதி செய்யப்பட்டது, எனவே அதை இங்கே இறக்குமதி செய்வது இந்த செருகுநிரலுக்குப் புரியாத அமைப்புகளைச் சேமிக்கும்.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d அமைப்பு இறக்குமதி செய்யப்பட்டது. கடவுச்சொற்களும் API விசைகளும் ஒருபோதும் ஏற்றுமதியில் சேர்க்கப்படுவதில்லை, எனவே அவற்றை மீண்டும் உள்ளிடவும்.' . "\0" . '%d அமைப்புகள் இறக்குமதி செய்யப்பட்டன. கடவுச்சொற்களும் API விசைகளும் ஒருபோதும் ஏற்றுமதியில் சேர்க்கப்படுவதில்லை, எனவே அவற்றை மீண்டும் உள்ளிடவும்.','Translate'=>'மொழிபெயர்','Manual overrides'=>'கைமுறை மேலெழுதல்கள்','Sitemaps and URLs'=>'தளவரைபடங்கள் மற்றும் URLகள்','General'=>'பொது','Who pays for the translation'=>'மொழிபெயர்ப்பிற்கு யார் பணம் செலுத்துகிறார்கள்','Either your Zinn Digital® plan, or an API key of your own. There is no free tier — somebody pays a provider for every word.'=>'உங்கள் Zinn Digital® திட்டம் அல்லது உங்களுடைய சொந்த API விசை. இலவச அடுக்கு எதுவும் இல்லை — ஒவ்வொரு வார்த்தைக்கும் யாரோ ஒருவர் வழங்குநருக்குப் பணம் செலுத்துகிறார்கள்.','My Zinn Digital® plan'=>'எனது Zinn Digital® திட்டம்','My own provider key'=>'எனது சொந்த வழங்குநர் விசை','Site ID'=>'தள ஐடி','From your Zinn Digital® dashboard, on this site\'s Translation tab.'=>'உங்கள் Zinn Digital® டாஷ்போர்டிலிருந்து, இந்த தளத்தின் Translation கீற்றில்.','Site token'=>'தள டோக்கன்','An API key from your Zinn Digital® dashboard, on its API keys page. Give it the sites.view and sites.translation.manage permissions.'=>'உங்கள் Zinn Digital® டாஷ்போர்டின் API விசைகள் பக்கத்திலிருந்து பெறப்பட்ட ஓர் API விசை. அதற்கு sites.view மற்றும் sites.translation.manage அனுமதிகளை வழங்கவும்.','Provider'=>'வழங்குநர்','API key'=>'API விசை','Your key, billed to you by the provider. It is stored on this site and sent only to them.'=>'வழங்குநரால் உங்களுக்குக் கட்டணம் விதிக்கப்படும் உங்கள் விசை. இது இந்தத் தளத்தில் சேமிக்கப்பட்டு அவர்களுக்கு மட்டுமே அனுப்பப்படும்.','Model'=>'மாதிரி','Leave empty for the cheapest model that does the job well.'=>'வேலையைச் சிறப்பாகச் செய்யும் மிகவும் மலிவான மாதிரியைத் தேர்ந்தெடுக்க இதை காலியாக விடவும்.','This site is written in'=>'இந்த தளம் எழுதப்பட்டுள்ள மொழி','Leave empty to use the site language from WordPress settings.'=>'WordPress அமைப்புகளிலிருந்து தளத்தின் மொழியைப் பயன்படுத்த காலியாக விடவும்.','Languages to publish'=>'வெளியிட வேண்டிய மொழிகள்','Each one gets its own web addresses and its own sitemap. Publish only the languages you want indexed.'=>'ஒவ்வொன்றும் தனக்கென சொந்த வலை முகவரிகளையும் சொந்த தள வரைபடத்தையும் பெறுகிறது. நீங்கள் அட்டவணைப்படுத்த விரும்பும் மொழிகளை மட்டும் வெளியிடுங்கள்.','Translate automatically when I publish or update'=>'நான் வெளியிடும் போது அல்லது புதுப்பிக்கும் போது தானாகவே மொழிபெயர்க்கவும்','Editing a page marks its translations out of date and they are remade in the background. Editing without changing any words costs nothing.'=>'ஒரு பக்கத்தைத் திருத்துவது அதன் மொழிபெயர்ப்புகளைக் காலாவதியானதாகக் குறிக்கும், மேலும் அவை பின்னணியில் மீண்டும் உருவாக்கப்படும். எந்த வார்த்தைகளையும் மாற்றாமல் திருத்துவதற்கு எந்தக் கட்டணமும் இல்லை.','What gets translated'=>'எவை மொழிபெயர்க்கப்படுகின்றன','Post types'=>'பதிவு வகைகள்','Translate the web addresses too'=>'வலைமுகவரிகளையும் மொழிபெயர்க்கவும்','French visitors get /fr/a-propos/ rather than /fr/about/. The untranslated address keeps working and redirects, so nothing that was indexed breaks.'=>'பிரெஞ்சு பார்வையாளர்கள் /fr/about/-க்கு பதிலாக /fr/a-propos/-ஐப் பெறுவார்கள். மொழிபெயர்க்கப்படாத முகவரி தொடர்ந்து செயல்பட்டு வழிமாற்றுகிறது, எனவே அட்டவணைப்படுத்தப்பட்ட எதுவும் உடைந்து போகாது.','Translate SEO titles, descriptions and image alt text'=>'SEO தலைப்புகள், விளக்கங்கள் மற்றும் பட மாற்று உரையை மொழிபெயர்க்கவும்','Translate categories and tags'=>'வகைகள் மற்றும் குறிச்சொற்களை மொழிபெயர்க்கவும்','Translate navigation menus'=>'வழிசெலுத்தல் மெனுக்களை மொழிபெயர்க்கவும்','Translate WooCommerce products and attributes'=>'WooCommerce தயாரிப்புகளையும் பண்புக்கூறுகளையும் மொழிபெயர்க்கவும்','Short descriptions, purchase notes, attribute labels and variation descriptions. Prices, SKUs and stored option values are never touched.'=>'குறுகிய விளக்கங்கள், கொள்முதல் குறிப்புகள், பண்புக்கூறு லேபிள்கள் மற்றும் மாறுபாடு விளக்கங்கள். விலைகள், SKUs மற்றும் சேமிக்கப்பட்ட விருப்ப மதிப்புகள் ஒருபோதும் மாற்றப்படாது.','SEO'=>'SEO','Add hreflang tags'=>'hreflang குறிச்சொற்களைச் சேர்க்கவும்','Tells search engines these pages are the same page in different languages. Leave this on unless another plugin is already doing it.'=>'இப்பக்கங்கள் வெவ்வேறு மொழிகளில் உள்ள ஒரே பக்கம் என்பதைத் தேடுபொறிகளுக்குத் தெரிவிக்கிறது. மற்றொரு செருகுநிரல் ஏற்கனவே இதைச் செய்யவில்லை என்றால் இதை இயக்கிய நிலையில் விடவும்.','Publish a sitemap for each language'=>'ஒவ்வொரு மொழிக்கும் ஒரு தள வரைபடத்தை வெளியிடுங்கள்','Publish llms.txt for each language'=>'ஒவ்வொரு மொழிக்கும் llms.txt-ஐ வெளியிடுக','A plain-text map of the site that AI answer engines read. They often cannot run JavaScript and may never fetch a sitemap.'=>'AI பதில் இயந்திரங்கள் வாசிக்கும் தளத்தின் எளிய உரை வரைபடம். அவை பெரும்பாலும் ஜாவாஸ்கிரிப்டை இயக்க முடியாது மற்றும் தள வரைபடத்தை ஒருபோதும் பெறாமல் போகலாம்.','Language switcher'=>'மொழி மாற்றி','Style'=>'பாணி','Colours, spacing and corners are on the Styling tab. Place it with the block, the [zinn_language_switcher] shortcode, or a menu.'=>'வண்ணங்கள், இடைவெளி மற்றும் மூலைகள் ஸ்டைலிங் தாவலில் உள்ளன. தொகுதி, [zinn_language_switcher] குறுக்குக்குறியீடு அல்லது மெனு மூலம் அதை வைக்கவும்.','Show only these languages'=>'இந்த மொழிகளை மட்டும் காட்டவும்','Leave empty to show every language you publish.'=>'நீங்கள் வெளியிடும் ஒவ்வொரு மொழியையும் காட்ட காலியாக விடவும்.','Name each language in its own language'=>'ஒவ்வொரு மொழியையும் அதன் சொந்த மொழியில் பெயரிடவும்','Deutsch rather than German. Somebody who cannot read the current page cannot read "German" either.'=>'German என்பதற்குப் பதிலாக Deutsch. தற்போதைய பக்கத்தைப் படிக்க முடியாத ஒருவரால் "German" என்பதையும் படிக்க முடியாது.','Show flags'=>'கொடிகளைக் காட்டு','Off by default: a language is not a country, and Arabic and Spanish have no single flag that does not exclude most of their speakers.'=>'இயல்புநிலையாக முடக்கப்பட்டுள்ளது: ஒரு மொழி என்பது ஒரு நாடு அல்ல, மேலும் அரபு மற்றும் ஸ்பானிஷ் மொழிகளுக்கு அவற்றைப் பேசுபவர்களில் பெரும்பான்மையானவர்களைத் தவிர்க்காத ஒற்றைக் கொடி எதுவும் இல்லை.','Include the language being read'=>'வாசிக்கப்படும் மொழியைச் சேர்க்கவும்','Include the original language'=>'அசல் மொழியைச் சேர்க்கவும்','Add it to this menu'=>'இதை இந்த மெனுவில் சேர்க்கவும்','Only the menu you name here. Nothing is added to any other menu on the site.'=>'நீங்கள் இங்கே பெயரிடும் மெனு மட்டுமே. தளத்திலுள்ள வேறு எந்த மெனுவிலும் எதுவும் சேர்க்கப்படாது.','Accent'=>'உச்சரிப்பு','Background'=>'பின்னணி','Text'=>'உரை','Corner radius'=>'மூலை ஆரம்','Spacing'=>'இடைவெளி','Text size'=>'உரை அளவு','Do not add it to a menu'=>'இதை மெனுவில் சேர்க்க வேண்டாம்','none'=>'எதுவுமில்லை','On a Zinn Digital® plan you choose the languages to publish on this site\'s Translation tab in your dashboard, under "Shown to visitors". This site checks it every hour. Publishing now: %s.'=>'Zinn Digital® திட்டத்தில் உங்கள் கட்டுப்பாட்டகத்தில் இந்தத் தளத்தின் மொழிபெயர்ப்புத் தாவலில், "பார்வையாளர்களுக்குக் காட்டப்படுவது" என்பதன் கீழ் வெளியிடுவதற்கான மொழிகளை நீங்கள் தேர்வுசெய்கிறீர்கள். இந்தத் தளம் ஒவ்வொரு மணி நேரமும் இதைச் சரிபார்க்கிறது. இப்போது வெளியிடப்படுகிறது: %s.','On a Zinn Digital® plan you choose the languages to publish on this site\'s Translation tab in your dashboard. This site has not read that choice yet, so it is still publishing: %s. Check the Site ID and token above.'=>'Zinn Digital® திட்டத்தில், உங்கள் முகப்புப்பலகையில் உள்ள இந்த தளத்தின் Translation தாவலில் வெளியிடுவதற்கான மொழிகளைத் தேர்வுசெய்கிறீர்கள். இந்த தளம் இன்னும் அந்தத் தேர்வைப் படிக்கவில்லை, எனவே இது இன்னும் வெளியிடுகிறது: %s. மேலே உள்ள Site ID மற்றும் டோக்கனைச் சரிபார்க்கவும்.','Edit any translation here. An edited translation is kept exactly as you wrote it and is never overwritten when the page is translated again.'=>'எந்தவொரு மொழிபெயர்ப்பையும் இங்கே திருத்தவும். திருத்தப்பட்ட மொழிபெயர்ப்பு நீங்கள் எழுதியபடியே துல்லியமாக வைக்கப்படும், மேலும் இப்பக்கம் மீண்டும் மொழிபெயர்க்கப்படும்போது ஒருபோதும் மேலெழுதப்படாது.','Every language'=>'அனைத்து மொழிகளும்','Search translations'=>'மொழிபெயர்ப்புகளைத் தேடுக','Filter'=>'வடிகட்டு','Content'=>'உள்ளடக்கம்','Language'=>'மொழி','Translation'=>'மொழிபெயர்ப்பு','Status'=>'நிலை','Save'=>'சேமி','Nothing translated yet. Publish a language and translation starts in the background.'=>'இதுவரை எதுவும் மொழிபெயர்க்கப்படவில்லை. ஒரு மொழியை வெளியிடுங்கள், பின்னணியில் மொழிபெயர்ப்பு தொடங்கும்.','These addresses are live. Open any of them to check it, and submit the sitemap index to Google Search Console.'=>'இந்த முகவரிகள் நேரலையில் உள்ளன. அதைச் சரிபார்க்க அவற்றில் ஏதேனும் ஒன்றைத் திறக்கவும், மேலும் தளவரைபடக் குறியீட்டை Google Search Console-இல் சமர்ப்பிக்கவும்.','You are not allowed to edit translations on this site.'=>'இந்த தளத்தில் மொழிபெயர்ப்புகளைத் திருத்துவதற்கு உங்களுக்கு அனுமதி இல்லை.','Edited by you — kept'=>'உங்களால் திருத்தப்பட்டது — தக்கவைக்கப்பட்டது','Source changed — will be redone'=>'மூலம் மாறியது — மீண்டும் செய்யப்படும்','Up to date'=>'புதுப்பித்த நிலையில் உள்ளது','Connected'=>'இணைக்கப்பட்டது','Connecting…'=>'இணைக்கிறது…','Connected, but something needs attention'=>'இணைக்கப்பட்டது, ஆனால் ஏதோ ஒன்று கவனம் செலுத்த வேண்டியுள்ளது','Not connected'=>'இணைக்கப்படவில்லை','Running on your own account'=>'உங்கள் சொந்தக் கணக்கில் இயங்குகிறது','We could not check this'=>'எங்களால் இதைச் சரிபார்க்க முடியவில்லை','This plugin did not say why. Send a diagnostics report and we will look.'=>'இந்தச் செருகுநிரல் அதற்கான காரணத்தைக் கூறவில்லை. கண்டறிதல் அறிக்கையை அனுப்புங்கள், நாங்கள் பார்க்கிறோம்.','Connection status'=>'இணைப்பு நிலை','Last checked %s ago.'=>'கடைசியாக %s முன்பு சரிபார்க்கப்பட்டது.','(opens in a new tab)'=>'(புதிய தாவலில் திறக்கும்)','Send this to Zinn® support'=>'இதை Zinn® ஆதரவுக்கு அனுப்பவும்','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'இதுவே துல்லியமாக அனுப்பப்படும் — வேறெதுவும் இல்லை, மறைக்கப்பட்டதும் எதுவுமில்லை. உங்கள் கடவுச்சொற்கள், டோக்கன்கள் மற்றும் API விசைகள் இதில் இல்லை.','The diagnostics report that will be sent'=>'அனுப்பப்படவுள்ள கண்டறிதல் அறிக்கை','Copy to clipboard'=>'கிளிப்போர்டுக்கு நகலெடு','Send this report to Zinn® support'=>'இந்த அறிக்கையை Zinn® ஆதரவுக்கு அனுப்பவும்','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'நாங்கள் உங்களுக்காக ஒரு ஆதரவு டிக்கெட்டைத் திறந்து மின்னஞ்சல் மூலம் பதிலளிக்கிறோம். நீங்கள் அதை அனுப்ப விரும்பவில்லை என்றால், மேலே உள்ளதை நகலெடுத்து நீங்களே ஒரு டிக்கெட்டில் ஒட்டவும்.','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'இந்த சேவையகத்திலிருந்து (%s) Zinn Digital®-ஐ அணுக முடியவில்லை. மேலே உள்ள அறிக்கையை நகலெடுத்து, அதற்குப் பதிலாக ஒரு டிக்கெட்டைத் திறக்கவும் — உங்கள் அமைப்புகளில் எந்தத் தவறும் இல்லை.','Sent. Zinn® support has your report and will reply by email.'=>'அனுப்பப்பட்டது. Zinn® ஆதரவுக் குழு உங்கள் அறிக்கையைப் பெற்றுள்ளது, மின்னஞ்சல் மூலம் பதிலளிக்கும்.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'அனுப்பப்பட்டது. Zinn® ஆதரவு உங்கள் அறிக்கையைப் பெற்றுள்ளது — குறிப்பு %s — மற்றும் மின்னஞ்சல் மூலம் பதிலளிக்கும்.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'குறுகிய காலத்தில் பல அறிக்கைகளை அனுப்பியுள்ளீர்கள். சில நிமிடங்கள் காத்திருந்து மீண்டும் முயற்சிக்கவும் — முந்தையவை வந்து சேர்ந்துவிட்டன.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® இப்போதைக்கு அறிக்கையை ஏற்க முடியவில்லை — இது எங்கள் பக்கப் பிரச்சனை, உங்களுடையது அல்ல. சிறிது நேரத்தில் மீண்டும் முயற்சிக்கவும், அல்லது மேலே உள்ள அறிக்கையை ஒரு டிக்கெட்டில் நகலெடுக்கவும்.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'அறிக்கை நிராகரிக்கப்பட்டது (HTTP %d). மேலே உள்ளதை நகலெடுத்து, அந்த எண்ணைக் குறிப்பிட்டு ஒரு டிக்கெட்டைத் திறக்கவும்.','%s — guides and services'=>'%s — வழிகாட்டிகள் மற்றும் சேவைகள்','User guides'=>'பயனர் வழிகாட்டிகள்','Read the %s user guide'=>'%s பயனர் வழிகாட்டியைப் படிக்கவும்','Hide this'=>'இதை மறைக்கவும்','Zinn® hosting for WordPress'=>'WordPress-க்கான Zinn® ஹோஸ்டிங்','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, தினசரி காப்புப் பிரதிகள், இலவச இடம்பெயர்வு மற்றும் ஒன்றுக்கும் மேற்பட்ட தளங்களை நிர்வகிப்பவர்களுக்காக உருவாக்கப்பட்ட ஒரு கட்டுப்பாட்டு பலகை.','The Zinn® marketplace'=>'Zinn® சந்தை','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'இரு தரப்பினரும் திருப்தி அடையும் வரை பணம் பாதுகாப்பாக வைக்கப்பட்டிருக்க, நிறுவப்பட்ட தளங்கள், டொமைன்கள் மற்றும் இணைப்பு இடங்களை வாங்கவும் விற்கவும்.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — இதைத் தொழிலாகச் செய்பவர்களைப் பணியமர்த்துங்கள்','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'எங்கள் உலகளாவிய ஃப்ரீலான்ஸ் சந்தை: எழுத்தாளர்கள், வடிவமைப்பாளர்கள், உருவாக்குநர்கள் மற்றும் எஸ்சிஓ நிபுணர்களின் 10,000-க்கும் மேற்பட்ட ஆயத்த சேவைகளை உலாவவும், அல்லது ஒரு திட்டத்தைப் பதிவிட்டு அவர்களை ஏலம் எடுக்க அனுமதிக்கவும்.','The API key was rejected. Check that it is still valid and has translation access, then save it again.'=>'API விசை நிராகரிக்கப்பட்டது. அது இன்னும் செல்லுபடியாகிறதா மற்றும் மொழிபெயர்ப்பு அணுகல் உள்ளதா என்பதைச் சரிபார்த்து, பின்னர் அதை மீண்டும் சேமிக்கவும்.','The provider refused on billing or quota. Nothing was translated. Check the balance and limits on your account with them.'=>'பில்லிங் அல்லது ஒதுக்கீடு காரணமாக வழங்குநர் மறுத்துவிட்டார். எதுவும் மொழிபெயர்க்கப்படவில்லை. அவர்களிடம் உள்ள உங்கள் கணக்கின் இருப்பு மற்றும் வரம்புகளைச் சரிபார்க்கவும்.','The translation provider is having a problem at their end. Nothing was translated or charged, and it will try again on the next pass.'=>'மொழிபெயர்ப்பு வழங்குநரின் பக்கத்தில் சிக்கல் ஏற்பட்டுள்ளது. எதுவும் மொழிபெயர்க்கப்படவோ கட்டணம் வசூலிக்கப்படவோ இல்லை, அடுத்த சுற்றில் மீண்டும் முயற்சி செய்யப்படும்.','The translation request failed and we could not tell why. Nothing was saved.'=>'மொழிபெயர்ப்பு கோரிக்கை தோல்வியடைந்தது, அதற்கான காரணத்தை எங்களால் அறிய முடியவில்லை. எதுவும் சேமிக்கப்படவில்லை.','Sitemap index'=>'தள வரைபட அட்டவணை','%s sitemap'=>'%s தள வரைபடம்','LLM content map'=>'LLM உள்ளடக்க வரைபடம்','%s LLM content map'=>'%s LLM உள்ளடக்க வரைபடம்','Languages published'=>'வெளியிடப்பட்ட மொழிகள்','Site language'=>'தளத்தின் மொழி','SEO plugin'=>'SEO செருகுநிரல்','No translation provider is set up yet.'=>'இன்னும் எந்த மொழிபெயர்ப்பு வழங்குநரும் அமைக்கப்படவில்லை.','Paste an API key from your chosen provider, or connect the site to a Zinn Digital® account, and translation starts on the next pass.'=>'நீங்கள் தேர்ந்தெடுத்த வழங்குநரிடமிருந்து API விசையை ஒட்டவும், அல்லது தளத்தை Zinn Digital® கணக்குடன் இணைக்கவும், அடுத்த சுற்றில் மொழிபெயர்ப்பு தொடங்கும்.','Translating with your own %s key.'=>'உங்களுடைய சொந்த %s விசையைக் கொண்டு மொழிபெயர்க்கிறது.','This site is not connected to a Zinn Digital® account, which is fine — your provider bills you directly.'=>'இந்தத் தளம் Zinn Digital® கணக்குடன் இணைக்கப்படவில்லை, இது பரவாயில்லை — உங்கள் வழங்குநர் உங்களுக்கு நேரடியாகக் கட்டணம் விதிக்கிறார்.','Not connected to Zinn Digital® yet.'=>'இன்னும் Zinn Digital® உடன் இணைக்கப்படவில்லை.','Add this site\'s ID and token from your Zinn Digital® dashboard, or switch to your own provider key to run without an account.'=>'உங்கள் Zinn Digital® கட்டுப்பாட்டகத்திலிருந்து இந்த தளத்தின் ID மற்றும் டோக்கனைச் சேர்க்கவும், அல்லது கணக்கு இல்லாமல் இயக்க உங்கள் சொந்த வழங்குநர் விசைக்கு மாறவும்.','Connected to Zinn Digital®.'=>'Zinn Digital® உடன் இணைக்கப்பட்டது.','The translation provider is having a problem.'=>'மொழிபெயர்ப்பு வழங்குநருக்கு ஒரு சிக்கல் ஏற்பட்டுள்ளது.','Translation is paused — your provider needs attention.'=>'மொழிபெயர்ப்பு இடைநிறுத்தப்பட்டுள்ளது — உங்கள் வழங்குநருக்குக் கவனம் தேவை.','Translation has not been set up yet.'=>'மொழிபெயர்ப்பு இன்னும் அமைக்கப்படவில்லை.','Something went wrong at our end.'=>'எங்கள் தரப்பில் ஏதோ தவறு நடந்துவிட்டது.','Check their status page'=>'அவர்களின் நிலைப் பக்கத்தைச் சரிபார்க்கவும்','Fix this on your account'=>'இதை உங்கள் கணக்கில் சரிசெய்யவும்','Style preset'=>'பாணி முன்னமைவு','A starting point. Anything below overrides it.'=>'ஒரு தொடக்கப் புள்ளி. கீழே உள்ள எதுவும் இதை மேலெழுதும்.','Use my own colours and sizes'=>'எனது சொந்த வண்ணங்கள் மற்றும் அளவுகளைப் பயன்படுத்தவும்','Leave this off and the preset is used exactly as it is.'=>'இதை முடக்கி வையுங்கள், முன்னமைவு அது இருக்கும் நிலையிலேயே துல்லியமாகப் பயன்படுத்தப்படும்.','Zinn® language switcher'=>'Zinn® மொழி மாற்றி','Let visitors read this page in another language.'=>'பார்வையாளர்கள் இந்தப் பக்கத்தை வேறொரு மொழியில் படிக்க அனுமதியுங்கள்.','Title'=>'தலைப்பு','Use the plugin setting'=>'செருகுநிரல் அமைப்பைப் பயன்படுத்தவும்','Dropdown'=>'கீழ்தோன்றும் பட்டியல்','Inline list'=>'உள்வரிப் பட்டியல்','Pills'=>'மாத்திரைகள்','Minimal text'=>'குறைந்தபட்ச உரை','Flags and names'=>'கொடிகளும் பெயர்களும்','Stacked list'=>'அடுக்கப்பட்ட பட்டியல்','Choose a language'=>'மொழியைத் தேர்ந்தெடுக்கவும்','See the Zinn Digital® release notes.'=>'Zinn Digital® வெளியீட்டுக் குறிப்புகளைப் பார்க்கவும்.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Zinn® புதுப்பிப்புச் சேவை இந்தப் புதுப்பிப்புக்கான பதிவிறக்க இணைப்பை வழங்கவில்லை. இந்த தளத்தால் Zinn® தளத்தை அணுக முடிகிறதா என்பதைச் சரிபார்த்து, பின்னர் மீண்டும் முயற்சிக்கவும்.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Zinn® புதுப்பிப்புச் சேவையிலிருந்து (%s) புதுப்பிப்பைப் பதிவிறக்க முடியவில்லை. சில நிமிடங்களில் மீண்டும் முயற்சிக்கவும்.','The downloaded update failed its integrity check and was not installed.'=>'பதிவிறக்கப்பட்ட புதுப்பிப்பு ஒருமைப்பாடு சரிபார்ப்பில் தோல்வியடைந்தது, அதனால் நிறுவப்படவில்லை.','No DeepL API key is saved, so there is nothing to translate with.'=>'எந்தவொரு DeepL API திறவுகோலும் சேமிக்கப்படவில்லை, எனவே மொழிபெயர்ப்பதற்கு எதுவும் இல்லை.','DeepL does not translate into %s. Choose Google Gemini or OpenAI for this language, or connect the site to Zinn Digital®.'=>'DeepL %s மொழியில் மொழிபெயர்க்காது. இந்த மொழிக்கு Google Gemini அல்லது OpenAI-ஐத் தேர்வுசெய்யவும், அல்லது தளத்தை Zinn Digital® உடன் இணைக்கவும்.','DeepL could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'DeepL உடன் தொடர்பு கொள்ள முடியவில்லை. எதுவும் மொழிபெயர்க்கப்படவில்லை, எந்தக் கட்டணமும் வசூலிக்கப்படவில்லை; அடுத்த சுற்றில் மீண்டும் முயற்சிக்கும்.','Your DeepL character quota is used up for this period. Translation resumes when it resets, or when you raise the limit on your DeepL account.'=>'இந்தக் காலக்கட்டத்திற்கான உங்கள் DeepL எழுத்து ஒதுக்கீடு முடிந்துவிட்டது. அது மீட்டமைக்கப்படும் போது அல்லது உங்கள் DeepL கணக்கில் வரம்பை அதிகரிக்கும் போது மொழிபெயர்ப்பு மீண்டும் தொடங்கும்.','DeepL answered with something we could not read. Nothing was saved.'=>'நாங்கள் படிக்க முடியாத ஒன்றை DeepL பதிலாக அளித்துள்ளது. எதுவும் சேமிக்கப்படவில்லை.','No Google Gemini API key is saved, so there is nothing to translate with.'=>'Google Gemini API விசை எதுவும் சேமிக்கப்படவில்லை, எனவே மொழிபெயர்ப்பதற்கு எதுவும் இல்லை.','Google Gemini could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'Google Gemini-ஐ அணுக முடியவில்லை. எதுவும் மொழிபெயர்க்கப்படவில்லை, எந்தக் கட்டணமும் வசூலிக்கப்படவில்லை; அடுத்த சுற்றில் மீண்டும் முயற்சிக்கும்.','No OpenAI API key is saved, so there is nothing to translate with.'=>'OpenAI API விசை எதுவும் சேமிக்கப்படவில்லை, எனவே மொழிபெயர்ப்பதற்கு எதுவும் இல்லை.','OpenAI could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'OpenAI-ஐ அணுக முடியவில்லை. எதுவும் மொழிபெயர்க்கப்படவில்லை, எந்தக் கட்டணமும் வசூலிக்கப்படவில்லை; அடுத்த சுற்றில் இது மீண்டும் முயற்சிக்கும்.','This site is not connected to Zinn Digital®, so there is nothing to collect. Add the Site ID and token, or switch to your own provider key.'=>'இந்த தளம் Zinn Digital® உடன் இணைக்கப்படவில்லை, எனவே சேகரிக்க எதுவும் இல்லை. தள ஐடி மற்றும் டோக்கனைச் சேர்க்கவும், அல்லது உங்கள் சொந்த வழங்குநர் விசைக்கு மாறவும்.','This site is not connected to Zinn Digital®.'=>'இந்த தளம் Zinn Digital® உடன் இணைக்கப்படவில்லை.','Zinn Digital® could not be reached. Nothing was sent; it will try again on the next pass.'=>'Zinn Digital®-ஐத் தொடர்பு கொள்ள முடியவில்லை. எதுவும் அனுப்பப்படவில்லை; அடுத்த சுற்றில் மீண்டும் முயற்சிக்கும்.','Translation is paused on this site. Check the account is up to date on your Zinn Digital® dashboard.'=>'இந்த தளத்தில் மொழிபெயர்ப்பு இடைநிறுத்தப்பட்டுள்ளது. உங்கள் Zinn Digital® டாஷ்போர்டில் கணக்கு புதுப்பித்த நிலையில் உள்ளதா எனச் சரிபார்க்கவும்.','Zinn Digital® rejected this site\'s token. It must be an API key with the sites.view and sites.translation.manage permissions — create one on the API keys page of your dashboard.'=>'Zinn Digital® இந்த தளத்தின் டோக்கனை நிராகரித்துவிட்டது. அது sites.view மற்றும் sites.translation.manage அனுமதிகளைக் கொண்ட API விசையாக இருக்க வேண்டும் — உங்கள் கட்டுப்பாட்டகத்தின் API விசைகள் பக்கத்தில் ஒன்றை உருவாக்கவும்.','Zinn Digital® could not be reached. Your site keeps serving the translations it already has.'=>'Zinn Digital®-ஐத் தொடர்பு கொள்ள முடியவில்லை. உங்கள் தளம் ஏற்கனவே உள்ள மொழிபெயர்ப்புகளைத் தொடர்ந்து வழங்கும்.','Zinn Digital® answered with something we could not read. Your site keeps serving the translations it already has.'=>'Zinn Digital® எங்களால் படிக்க முடியாத ஒன்றைக் கொண்டு பதிலளித்தது. உங்கள் தளம் ஏற்கனவே உள்ள மொழிபெயர்ப்புகளைத் தொடர்ந்து வழங்குகிறது.','Zinn Digital® could not be reached. Your site keeps publishing the languages it already has.'=>'Zinn Digital®-ஐத் தொடர்பு கொள்ள முடியவில்லை. உங்கள் தளம் ஏற்கனவே உள்ள மொழிகளைத் தொடர்ந்து வெளியிடுகிறது.','Zinn Digital® answered with something we could not read. Your site keeps publishing the languages it already has.'=>'Zinn Digital® எங்களால் படிக்க முடியாத ஒன்றைக் கொண்டு பதிலளித்தது. உங்கள் தளம் ஏற்கனவே உள்ள மொழிகளைத் தொடர்ந்து வெளியிடுகிறது.']];